/** Fictional cashflow: 1,000 credits/week are generated by 16 baseline productive posts. */
import {EMPLOYEES} from '../data/continuous/employees.js';
import {roster,sectorStaffing} from './staffing-management.js';
export const FINANCE_RULES=Object.freeze({baseRevenue:1000,basePosts:16,quarters:[12,24,48],targets:{12:1800,24:4200,48:9000},maxWeeks:260});
const round=n=>Math.round(n*100)/100;
export function ensureFinance(s){s.finance??={ledger:[],lastWeek:s.week,earned:0,operationalCosts:0};return s.finance;}
export function financePreview(s){
 const people=roster(s),sectors=['escritorio','producao','atendimento'];
 const active=people.filter(p=>s.staff?.[p.id]?.employment==='active');
 const originalActive=active.filter(p=>EMPLOYEES.some(x=>x.id===p.id)).length;
 const hiresActive=active.length-originalActive;
 const temporary=sectors.reduce((n,id)=>n+sectorStaffing(s,id).temporary,0);
 // Capacity is capped at the original 16 operational posts. Coverage and hiring
 // replace missing capacity, but cannot mint unlimited revenue.
 const productivePosts=Math.min(FINANCE_RULES.basePosts,active.length+temporary);
 const revenue=round(FINANCE_RULES.baseRevenue*productivePosts/FINANCE_RULES.basePosts);
 const costs=(s.staffing?.weekly===undefined?0:0);
 return {base:FINANCE_RULES.baseRevenue,productivePosts,originalActive,hiresActive,temporary,revenue,
  lostRevenue:round(FINANCE_RULES.baseRevenue-revenue),perPost:FINANCE_RULES.baseRevenue/FINANCE_RULES.basePosts};
}
export function financeWeek(s,weeklyCost=0){
 const finance=ensureFinance(s);if(finance.lastWeek>=s.week)return null;
 const preview=financePreview(s);const line={week:s.week,revenue:preview.revenue,costs:weeklyCost,
  profit:round(preview.revenue-weeklyCost),productivePosts:preview.productivePosts,lostRevenue:preview.lostRevenue};
 s.budget=Math.max(0,round(s.budget+line.revenue));finance.earned=round(finance.earned+line.revenue);
 finance.operationalCosts=round(finance.operationalCosts+weeklyCost);
 finance.lastWeek=s.week;finance.ledger.push(line);finance.ledger=finance.ledger.slice(-FINANCE_RULES.maxWeeks);
 return line;
}
export function financePeriods(s){
 const f=ensureFinance(s);
 const period=(weeks)=>{const n=Math.floor((s.week-1)/weeks),start=2+n*weeks,end=1+(n+1)*weeks;
  const completed=s.week>=end;
  const lines=f.ledger.filter(l=>l.week>=start&&l.week<=Math.min(s.week,end));
  const revenue=round(lines.reduce((n,l)=>n+l.revenue,0));
  const costs=round(lines.reduce((n,l)=>n+l.costs,0));
  const profit=round(revenue-costs);
  const goal=FINANCE_RULES.targets[weeks];
  return {weeks,start,end,completed,revenue,costs,profit,goal,achieved:completed?profit>=goal:null,
   weeksRecorded:lines.length};
 };
 return {quarter:period(12),semester:period(24),year:period(48),history:f.ledger,
  earned:f.earned,costs:f.operationalCosts,preview:financePreview(s)};
}
export function validateFinance(s){
 if(s.finance===undefined)return true;const f=s.finance;
 if(!f||!Array.isArray(f.ledger)||f.ledger.length>FINANCE_RULES.maxWeeks||
  !Number.isInteger(f.lastWeek)||f.lastWeek>s.week||
  !Number.isFinite(f.earned)||f.earned<0||!Number.isFinite(f.operationalCosts)||f.operationalCosts<0)throw Error('invalid-finance');
 for(const row of f.ledger)if(!Number.isInteger(row.week)||row.week>s.week||!Number.isFinite(row.revenue)||row.revenue<0||
  !Number.isFinite(row.costs)||row.costs<0||!Number.isFinite(row.profit))throw Error('invalid-finance-row');
 return true;
}
